obj=[[8,8,8,1,7],[8,1,0,0,1],[7,0,1,1,7]]
# use given grid
rows=18; cols=14
g=[[8]*cols for _ in range(rows)]
# original object coordinates row2 col8
for i in range(3):
 for j in range(5):
  if obj[i][j]!=8:g[2+i][8+j]=obj[i][j]
marks=[(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]
for r,c in marks:
 for i in range(3):
  for j in range(5):
   rr=r+i-1; cc=c+j-2
   if 0<=rr<rows and 0<=cc<cols and obj[i][j]!=8:g[rr][cc]=obj[i][j]
print('\n'.join(' '.join(map(str,x)) for x in g))
